// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  let googleQuery = '';
  item.json.Email.split(',').forEach((email, i) => {
    googleQuery += i !== 0 ? ' OR ' : ''
    googleQuery += `from:${email} OR to:${ email }`

  })

  // Only search messages since the last successful sync for this account --
  // avoids re-fetching (and the sub-workflow re-logging) a client's entire
  // mailbox history on every run once they already have a conversation
  // sheet. A brand-new account has no last_synced_at yet, so it still gets
  // the full history, same as before this existed.
  const lastSyncedAt = item.json.last_synced_at;
  if (lastSyncedAt) {
    const d = new Date(lastSyncedAt);
    if (!isNaN(d.getTime())) {
      const gmailDate = `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}`;
      googleQuery += ` after:${gmailDate}`;
    }
  }
  item.json.googleQuery = googleQuery;
}

return $input.all();

// Loop over input items and build the Outlook search text plus the per-mailbox date rules.
//  * Jack (the original Outlook mailbox): only messages after last_synced_at (as before).
//  * Mia / Eve / Yolanda (added later): the FULL history until a client has been backfilled
//    once (new_outlook_backfilled = TRUE); after that only messages after last_synced_at.
for (const item of $input.all()) {
  let outlookQuery = '';
  item.json.Email.split(',').forEach((email, i) => {
    outlookQuery += i !== 0 ? ' OR ' : ''
    outlookQuery += `${email}`
  })
  item.json.outlookQuery = outlookQuery;
  const last = String(item.json.last_synced_at || '').trim();
  const backfilled = String(item.json.new_outlook_backfilled || '').trim().toLowerCase() === 'true';
  item.json.after_jack = last;
  item.json.after_new_mailboxes = backfilled ? last : '';
}

return $input.all();

const items = $input.all();
const output = [];
const head_email = $input.first().json.Email
for (const item of items) {
  const json = item.json;

  // Split emails
  const emails = (json.Email || "")
    .split(',')
    .map(e => e.trim())
    .filter(Boolean);

  // Parse Platform safely -- this used to only ever see a JSON-array string
  // (e.g. '["gmail","outlook"]') because plain single-provider accounts
  // ("gmail" / "outlook" with no brackets) were routed down a separate,
  // now-removed path instead of reaching this node. Now every account comes
  // through here, so a plain string must also be accepted -- treated as a
  // single-element array, which the rest of this function already handles
  // correctly as the "one provider" case.
  let platforms = [];
  const rawPlatform = json.Platform;
  if (Array.isArray(rawPlatform)) {
    platforms = rawPlatform;
  } else {
    try {
      const parsed = JSON.parse(rawPlatform);
      platforms = Array.isArray(parsed) ? parsed : [parsed];
    } catch {
      platforms = rawPlatform ? [rawPlatform] : [];
    }
  }

  // Existing client (it already has a last_synced_at): ignore the Platform column and look in
  // ALL mailboxes (3 Gmail + 4 Outlook) -- Platform may be incomplete for older rows.
  if (String(json.last_synced_at || '').trim() !== '' && emails.length) {
    output.push({ json: { ...json, mails: head_email, Email: emails.join(','), Platform: 'gmail' } });
    output.push({ json: { ...json, mails: head_email, Email: emails.join(','), Platform: 'outlook' } });
    continue;
  }

  // ---- CASE 1: Single email, multiple platforms ----
  if (emails.length === 1 && platforms.length > 1) {
    for (const rawPlatform of platforms) {
      if (!rawPlatform) continue;
      // Normalize + validate the same way CASE 2 below already does --
      // this branch used to pass the raw array value straight through
      // unchecked, so anything other than an exact lowercase "gmail" or
      // "outlook" (e.g. "Gmail", a stray space) would silently fail the
      // downstream "Gmail or Outlook?" equality check and get routed to
      // Outlook regardless of what it actually was, with no error.
      const platform = String(rawPlatform).trim().toLowerCase();
      if (platform !== 'gmail' && platform !== 'outlook') continue;

      output.push({
        json: {
          ...json,
          Email: emails[0],
          mails:head_email,
          Platform: platform
        }
      });
    }
    continue;
  }

  // ---- CASE 2: Multiple emails (normal mapping) ----
  const gmailEmails = [];
  const outlookEmails = [];

  for (let i = 0; i < emails.length; i++) {
    const email = emails[i];
    const platform = platforms[i];

    if (!platform || platform === "None") continue;

    if (Array.isArray(platform)) {
      if (platform.includes("gmail")) gmailEmails.push(email);
      if (platform.includes("outlook")) outlookEmails.push(email);
    } else {
      if (platform === "gmail") gmailEmails.push(email);
      if (platform === "outlook") outlookEmails.push(email);
    }
  }

  if (gmailEmails.length) {
    output.push({
      json: {
        ...json,
         mails:head_email,
        Email: gmailEmails.join(','),
        Platform: "gmail"
      }
    });
  }

  if (outlookEmails.length) {
    output.push({
      json: {
        ...json,
        mails:head_email,
        Email: outlookEmails.join(','),
        Platform: "outlook"
      }
    });
  }

  // Neither branch matched anything for this account -- e.g. Platform is
  // blank/unset (a row that hasn't been classified yet). Returning zero
  // items here would silently kill the loop: n8n stops the whole branch
  // when a node produces no output, which breaks the loop-back into
  // "For Each Account" and stalls every account still queued after this
  // one, not just this one. Emit an explicit "unclassified" marker
  // instead so the next node can route it straight back to the loop.
  if (!gmailEmails.length && !outlookEmails.length) {
    output.push({ json: { ...json, mails: head_email, Platform: '' } });
  }
}

return output;

const items = $input.all();
const data = $('Build Gmail Search Query').item.json;
const row_number = data.row_number;
const querymail = data.mails;
const allMessages = [];

for (const item of items) {
  const messages = item.json.messages || [];
  const fromEmail = item.json.by_mail; // get sender for this batch

  messages.forEach(msg => {
    allMessages.push({
      ...msg,
      from_email: fromEmail, // attach sender to each message
    });
  });
}

return [
  {
    json: {
      row_number:row_number,
      querymail:querymail,
      resource: 'gmail',
      email: $input.first().json.to_mail,
      name: $input.first().json.Name,
      messages: allMessages
    }
  }
];

const items = $input.all();
if (!items.length) return [];

// Find gmail & outlook objects safely
const gmailItem = items.find(i => i.json.resource === 'gmail');
const outlookItem = items.find(i => i.json.resource === 'outlook');

// ------------------
// Merge base fields
// ------------------
const merged = {
  row_number: gmailItem?.json.row_number ?? outlookItem?.json.row_number,
  name: gmailItem?.json.name ?? outlookItem?.json.name,
  querymail: gmailItem?.json.querymail ?? outlookItem?.json.querymail,

  // Combined resource string
  resource: items.map(i => i.json.resource).join(','),

  gmail: gmailItem
    ? {
        email: gmailItem.json.email,
        messages: gmailItem.json.messages || []
      }
    : null,

  outlook: outlookItem
    ? {
        email: outlookItem.json.email,
        ids: outlookItem.json.ids || [],
        entries: outlookItem.json.entries || (outlookItem.json.ids || []).map(id => ({ id, by_mail: 'outlook_jack' }))
      }
    : null
};

// ------------------
// Email merge + dedup
// ------------------
const rawEmails = [
  merged.gmail?.email,
  merged.outlook?.email
].filter(Boolean);

const combinedEmails = [
  ...new Set(
    rawEmails
      .flatMap(e => e.split(','))
      .map(e => e.trim())
      .filter(Boolean)
  )
].join(',');

// ------------------
// Drive parent folders
// ------------------
// Three Drive parents exist: gmail-only clients, outlook-only clients and dual-provider
// clients. A NEW client's folder is created under the parent that matches where its
// messages actually are (a provider only counts if it returned messages -- every account
// now searches all mailboxes, so "searched" no longer says where the conversation is).
// An EXISTING client keeps its folder wherever it already is: the folder search below looks
// in all three parents (preferred one first) and only creates a folder if none has it.
const GMAIL_PARENT = '1-1EdTSWeoFPnbRa_hKdYsX4aMnqiQSSE';
const OUTLOOK_PARENT = '1L5xu6tTaS6yZXbHpTrpE4IQ1xjV8G_J8';
const COMBINED_PARENT = '102oeld1yMYGMmWs2Od198HqO1KeVhv_n';
const hasG = !!(merged.gmail && merged.gmail.messages.length);
const hasO = !!(merged.outlook && merged.outlook.ids.length);
let folder_id;
if (hasG && hasO) folder_id = COMBINED_PARENT;
else if (hasG) folder_id = GMAIL_PARENT;
else if (hasO) folder_id = OUTLOOK_PARENT;
else if (merged.gmail && merged.outlook) folder_id = COMBINED_PARENT;
else if (merged.gmail) folder_id = GMAIL_PARENT;
else folder_id = OUTLOOK_PARENT;
const parents = [folder_id, ...[COMBINED_PARENT, GMAIL_PARENT, OUTLOOK_PARENT].filter(p => p !== folder_id)];

// ------------------
// Final output object
// ------------------
return [
  {
    json: {
      row_number: merged.row_number,
      name: merged.name,
      querymail: merged.querymail,
      resource: merged.resource,
      email: combinedEmails,
      gmail: merged.gmail,
      outlook: merged.outlook,
      // true when the Outlook branch ran for this account, so Mark Account Processed can
      // record that the Outlook mailboxes (incl. the 3 newer ones) have been checked
      outlookSearched: !!merged.outlook,
      folder_id,
      parents
    }
  }
];

const items = $items('Combine Gmail & Outlook Per Client', 0);
const results = [];

for (const item of items) {
  const data = item.json;

  const base = {
    row_number: data.row_number,
    name: data.name,
  };

  // Gmail object
  if (data.gmail) {
    results.push({
      json: {
        ...base,
        resource: 'gmail',
        email: data.gmail.email,
        messages: data.gmail.messages
      }
    });
  }

  // Outlook object (entries = every id with the mailbox it came from)
  if (data.outlook) {
    results.push({
      json: {
        ...base,
        resource: 'outlook',
        email: data.outlook.email,
        ids: data.outlook.ids,
        entries: data.outlook.entries
      }
    });
  }
}

return results;

// Microsoft Graph does not allow combining $search (needed here to match "from OR to" across
// possibly multiple addresses in one query) with $filter (needed for a receivedDateTime range)
// in the same request, and toRecipients isn't filterable via $filter at all. So the date
// scoping happens here, client-side, after the search returns.
// MAILBOX tags every id with the mailbox it came from -- the Outlook Processor uses the tag
// to fetch the message with the right credential (message ids are only valid in their own mailbox).
const MAILBOX = 'outlook_jack';
const rowdata = $('Build Outlook Search Query').item.json;
const afterText = MAILBOX === 'outlook_jack' ? rowdata.after_jack : rowdata.after_new_mailboxes;
const lastSyncedAt = afterText ? new Date(afterText) : null;
const isNewEnough = (item) => {
  if (!lastSyncedAt || isNaN(lastSyncedAt.getTime())) return true;
  const ts = item.json.receivedDateTime || item.json.sentDateTime;
  if (!ts) return true;
  return new Date(ts) >= lastSyncedAt;
};

// oldest first
const messages = [...$input.all()].filter(isNewEnough).reverse();
const ids = messages.map(item => item.json.id).filter(id => id);

// Always report that this mailbox WAS searched (even with no ids), so the account can be
// marked as backfilled; the combine step drops mailboxes without ids from the queue.
return [{ json: {
  mailbox: MAILBOX,
  searched: true,
  ids,
  row_number: rowdata.row_number,
  querymail: rowdata.mails,
  email: rowdata.Email,
  name: rowdata.Name
} }];

const first = $input.first().json;
// every id carries the mailbox it was found in (outlook_jack / outlook_mia / outlook_eve /
// outlook_yolanda); older callers that only send ids are treated as the original mailbox
const entries = first.entries || (first.ids || []).map(id => ({ id, by_mail: 'outlook_jack' }));

const sheet_id = $('📄 Conversation Sheet (Resolved)').item.json.spreadsheetId;
const mainf4_id = $('📁 Client Root Folder (Resolved)').item.json.id;
const subf5_id = $('📁 Attachments Subfolder (Resolved)').item.json.id;

const row_number = first.row_number;

return entries.map((e, i) => ({
  json: {
    id: e.id,
    row_number,
    by_mail: e.by_mail,
    sheet_id,
    mainf4_id,
    subf5_id,
    index: i,
    // existing Processed column (no separate lowercase 'processed' column); source stays blank for
    // Outlook rows -- the Outlook Processor recognises its rows by by_mail (outlook_*)
    Processed: false
  }
}));

// Get messages array from previous node
const messagesArr = $input.first().json.messages
const row_number = $input.first().json.row_number
// Get parent info
const sheet_id = $('📄 Conversation Sheet (Resolved)').item.json.spreadsheetId;
const mainf4_id = $('📁 Client Root Folder (Resolved)').item.json.id;
const subf5_id = $('📁 Attachments Subfolder (Resolved)').item.json.id;

// Map over messages array
return messagesArr.map((msg, index) => ({
  json: {
    id: msg.id,
    row_number:row_number,
    threadId: msg.threadId,  // include threadId if needed
    by_mail: msg.from_email,
    sheet_id,
    mainf4_id,
    subf5_id,
    index,
    source: 'email',
    Processed:false
  }
}));

// Match on the client's name only, not the trailing "<email1,email2>" suffix --
// the email list is recomputed fresh every run from whatever this run's Gmail/
// Outlook search actually turned up, so it can drift from what got baked into
// the real folder's name at creation time (a new alias appears, order shifts,
// etc.) and an exact full-string match would then never hit again, forcing a
// duplicate folder. The name is the stable identity; the email suffix isn't.
// The search ran once per Drive parent folder, so $input holds the candidates of all three.
const expectedName = $('Combine Gmail & Outlook Per Client').item.json.name.toString().trim().toLowerCase();
const exact = $input.all().find(item => {
  const folderName = (item.json.name || '').toString().trim().toLowerCase();
  return folderName === expectedName || folderName.startsWith(expectedName + ' <');
});
return [exact || { json: { id: '', name: '' }, pairedItem: { item: 0 } }];

const expected = ('attachments').toString().trim().toLowerCase();
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === expected);
return [exact || { json: { id: '', name: '' } }];

const expected = "conversation";
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === expected);
if (!exact) return [{ json: { id: '', name: '', spreadsheetId: '' } }];
return [{ json: { ...exact.json, spreadsheetId: exact.json.id } }];

// Which control-sheet rows this run works on.
//  * new rows / reset rows: Processed = FALSE (the normal case, as before)
//  * existing rows still owed the one-time pull of the 3 new Outlook mailboxes:
//    Processed = TRUE, last_synced_at filled, new_outlook_backfilled not TRUE
// Rows without an Email (name-only rows) are never processed. `onlyClient` limits the
// run to one client (name or email contains the text) for a safe first test, and
// `maxAccountsPerRun` keeps one run from trying to do hundreds of clients.
const cfg = $('Run Config').first().json;
const only = String(cfg.onlyClient || '').trim().toLowerCase();
const max = Math.max(1, Number(cfg.maxAccountsPerRun) || 20);
const val = (v) => String(v ?? '').trim().toLowerCase();
const rows = $input.all().filter(i => {
  const j = i.json;
  if (!val(j.Email)) return false;
  if (only && !(val(j.Name).includes(only) || val(j.Email).includes(only))) return false;
  return true;
});
// A row with no Platform and no last_synced_at cannot be processed (the Platform check skips it and
// nothing ever marks it done), e.g. clients flagged "no conversation found". Leaving them in would
// keep them at the front of the queue and use up the run's slots forever.
const processable = (j) => val(j.Platform) !== '' || val(j.last_synced_at) !== '';
const pending = rows.filter(i => val(i.json.Processed) === 'false' && processable(i.json));
const backfill = rows.filter(i => val(i.json.Processed) === 'true' && val(i.json.last_synced_at) !== '' && val(i.json.new_outlook_backfilled) !== 'true');
return [...pending, ...backfill].slice(0, max);

// Joins the four Outlook mailbox results of one account into the single "outlook" item the
// rest of the workflow already expects, and keeps the mailbox of every id (entries) so the
// queue row can say which mailbox to fetch it from.
const items = $input.all().map(i => i.json).filter(j => j && j.searched);
if (!items.length) return [];
const first = items[0];
const entries = [];
for (const j of items) for (const id of (j.ids || [])) entries.push({ id, by_mail: j.mailbox });
return [{ json: {
  row_number: first.row_number,
  querymail: first.querymail,
  resource: 'outlook',
  email: first.email,
  by_mail: 'outlook',
  name: first.name,
  ids: entries.map(e => e.id),
  entries,
  outlookSearched: true
} }];

// Microsoft Graph does not allow combining $search (needed here to match "from OR to" across
// possibly multiple addresses in one query) with $filter (needed for a receivedDateTime range)
// in the same request, and toRecipients isn't filterable via $filter at all. So the date
// scoping happens here, client-side, after the search returns.
// MAILBOX tags every id with the mailbox it came from -- the Outlook Processor uses the tag
