const MAILBOX = 'outlook_mia';
const rowdata = $('Build Outlook Search Query').item.json;
const afterText = MAILBOX === 'outlook_jack' ? rowdata.after_jack : rowdata.after_new_mailboxes;
const lastSyncedAt = afterText ? new Date(afterText) : null;
const isNewEnough = (item) => {
  if (!lastSyncedAt || isNaN(lastSyncedAt.getTime())) return true;
  const ts = item.json.receivedDateTime || item.json.sentDateTime;
  if (!ts) return true;
  return new Date(ts) >= lastSyncedAt;
};

// oldest first
const messages = [...$input.all()].filter(isNewEnough).reverse();
const ids = messages.map(item => item.json.id).filter(id => id);

// Always report that this mailbox WAS searched (even with no ids), so the account can be
// marked as backfilled; the combine step drops mailboxes without ids from the queue.
return [{ json: {
  mailbox: MAILBOX,
  searched: true,
  ids,
  row_number: rowdata.row_number,
  querymail: rowdata.mails,
  email: rowdata.Email,
  name: rowdata.Name
} }];

// Microsoft Graph does not allow combining $search (needed here to match "from OR to" across
