// One item per Drive parent folder, preferred parent first, so the folder search below runs in
// every parent and finds an existing client folder wherever it lives.
const j = $input.first().json;
return j.parents.map(p => ({ json: { ...j, folder_id: p }, pairedItem: { item: 0 } }));
